			});
			 
            all.Add(new ParagraphTypeDetails()
            {    
                Code = "96", 
                SearchFields = "96,קנס לסוכני מכס", 
                Inactive = false, 
                LocalName = "קנס לסוכני מכס", 
			});
			 
            all.Add(new ParagraphTypeDetails()
            {    
                Code = "97", 
                SearchFields = "97,עיצום כספי לחוקיות יבוא", 
                Inactive = false, 
                LocalName = "עיצום כספי לחוקיות יבוא", 
